"""Build the two dependency-free, structurally parallel gallery pages."""
from pathlib import Path
from html import escape
ROOT=Path(__file__).resolve().parent
REPO='https://github.com/Sunwood-ai-labs/witness-battleship'
RAW='https://raw.githubusercontent.com/Sunwood-ai-labs/witness-battleship/main'
COPY={
'ja':dict(title='WITNESS — 近未来戦艦 CAD アーカイブ',desc='架空の近未来戦艦 WITNESS の CAD とビジュアル・アーカイブ。全体基準 V62、限定区画比較 V102、実画像、検証・復元手順を公開。',skip='本文へ移動',nav=['比較','ギャラリー','モデル','検証'],edition='PUBLIC CAD ARCHIVE / 01',status='進行中のデザイン研究',subtitle='形をつくる。<br>差分を、確かめる。',intro='架空の近未来戦艦を、形状と検証の両側から。<br>全体の基準モデルと、船側の局所比較を公開しています。',heroNote='全体比較の After 画像。V102 単体に全艦の部品が入っていることを示すものではありません。',cta='モデルを見る',repo='GitHub を開く',compareTitle='奥行きが、意匠を変える。',compareIntro='船側パネルの Before / After を同じ視点で比較。スライダーを動かすと、外周の縁・凹部・影の違いを確認できます。',hint='ドラッグ、または矢印キーで比較',slider='比較位置',compareNote='比較案の表示であり、基準モデルへの採用を意味しません。',views=['全体','BAY 0','BAY 1'],viewDescriptions=['全景の比較。船側の変更は局所的です。','5 枚の暖色パネル周囲の凹部と縁を比較します。','6 枚の暖色パネル列の外周と奥行きを比較します。'],galleryTitle='全景から、内部の配置まで。',galleryIntro='実際の CAD 由来画像 8 枚。拡大して形状を確認し、原寸 PNG へ進めます。フロアマップは表示用合成であり、統合済み全艦 CAD ではありません。',galleryNames=['全景 · Before','全景 · After','BAY0 · Before','BAY0 · After','BAY1 · Before','BAY1 · After','D4 · 生活・医療区画','D9 · 上部艦橋'],modelsTitle='2 つのモデル。異なる役割。',modelsIntro='全体を見るための基準と、局所形状を検証するための比較案。版を混ぜずに、目的に合うファイルから始めてください。',v62Title='艦全体の基準スナップショット',v62Desc='35,761 オブジェクトを収めた全体モデル。16 個の分割圧縮ファイルから復元します。後続の局所追加をすべて統合した最新版ではありません。',v62Detail='85,981,279 bytes / 復元後 FCStd',restore='復元ガイド',v102Title='2 区画の累積形状比較',v102Desc='船殻 1 部品に、付属形状 13 部品。2 つの除去領域を元船殻から引いた比較モデルです。艦橋や砲塔を含む全艦組立ではありません。',v102Detail='77,071 bytes / FCStd 直接取得',download='V102 をダウンロード',progressTitle='局所検証の現在地',progressDesc='14 区画のうち 2 区画を個別検証。残り 12 区画は未完です。この割合は、全艦の完成率・再現率ではありません。',verified='区画を個別検証',adopted='基準版への採用',verifyTitle='見た目だけで、終わらせない。',verifyIntro='配布の整合と復元結果を検証できる、公開スクリプトを添えています。',checks=['配布ファイルのサイズと SHA-256 を照合','16 片・結合 ZIP・復元 FCStd を段階的に検証','既存の復元ファイルは上書きしない','FreeCAD 形状検証は別環境で実行'],verifyNote='CI は配布スクリプトの検査を行います。FreeCAD の形状・描画検証は CI の対象外です。実船の設計、強度、水密、製造・安全認証には使用できません。',docs=['はじめて開く','モデルガイド','検証の範囲','版の違い'],closingTitle='モデルを開いて、<br>次の形を考える。',closingDesc='FreeCAD 1.0R での新規オープンを確認済み。<br>編集は作業コピーで。公開基準ファイルはそのままに。',start='はじめてのガイド',rights='公開は新たなライセンスの付与を意味しません。',footer='架空艦の CAD 研究 / 非製造用',close='閉じる',original='原寸 PNG を開く',galleryAction='画像を拡大',langLabel='表示言語',readme='README.ja.md'),
'en':dict(title='WITNESS — Future battleship CAD archive',desc='Explore WITNESS, a fictional future battleship CAD archive: V62 whole-model baseline, V102 local comparison, actual renders, and verified restoration tools.',skip='Skip to content',nav=['Compare','Gallery','Models','Verify'],edition='PUBLIC CAD ARCHIVE / 01',status='A design study in progress',subtitle='Build the form.<br>Examine the difference.',intro='A fictional future battleship, explored through geometry and evidence. A whole-model baseline, alongside focused hull comparisons.',heroNote='Whole-view After comparison. This image does not mean the V102 file contains the complete ship assembly.',cta='Explore the models',repo='View on GitHub',compareTitle='Depth makes the difference.',compareIntro='Compare the hull panels from the same viewpoint. Move the slider to examine the edges, recesses, and shadows—not just the silhouette.',hint='Drag, or use the arrow keys',slider='Comparison position',compareNote='A visual comparison of proposals, not an adoption into the baseline.',views=['WHOLE','BAY 0','BAY 1'],viewDescriptions=['Whole-view comparison. Hull changes are local.','Compare the recess and border around five warm panels.','Compare the outer edge and depth around six warm panels.'],galleryTitle='From silhouette to interior layout.',galleryIntro='Eight actual CAD-derived images. Enlarge each view, then inspect the original PNG. Floor maps are display composites, not integrated whole-ship CAD models.',galleryNames=['Whole · Before','Whole · After','BAY0 · Before','BAY0 · After','BAY1 · Before','BAY1 · After','D4 · Living & medical','D9 · Upper bridge'],modelsTitle='Two models. Different purposes.',modelsIntro='A baseline for the whole ship. A comparison for local geometry. Keep the versions distinct, and start with the file that answers your question.',v62Title='The whole-model baseline',v62Desc='A snapshot with 35,761 objects, restored from 16 compressed parts. It is not a latest integrated whole-ship model containing every later local addition.',v62Detail='85,981,279 bytes / restored FCStd',restore='Restoration guide',v102Title='A cumulative two-bay comparison',v102Desc='One hull and 13 accessory shapes. Two removal regions are subtracted from the baseline hull. This is not a complete assembly with the bridge and turrets.',v102Detail='77,071 bytes / direct FCStd',download='Download V102',progressTitle='Local validation, clearly scoped',progressDesc='2 of 14 bays individually verified; 12 remain unfinished. This ratio is not a whole-ship completion or fidelity score.',verified='BAYS INDIVIDUALLY VERIFIED',adopted='BASELINE ADOPTIONS',verifyTitle='Beyond a convincing image.',verifyIntro='Public tools let you verify distribution integrity and the restored native file.',checks=['Match distribution file sizes and SHA-256 hashes','Verify all 16 parts, the combined ZIP, and the native FCStd','Never overwrite an existing restored output','Run geometry checks in a separate FreeCAD environment'],verifyNote='CI checks the distribution scripts. FreeCAD geometry and rendering are not tested in CI. Not for real-vessel design, structural, watertightness, manufacturing, or safety certification.',docs=['Getting started','Model guide','Verification scope','Version differences'],closingTitle='Open the model.<br>Explore what comes next.',closingDesc='Fresh-open checks performed in FreeCAD 1.0R.<br>Edit a working copy. Preserve the public baseline.',start='Get started',rights='Public availability does not grant a new license.',footer='FICTIONAL SHIP CAD STUDY / NOT FOR MANUFACTURE',close='Close',original='Open original PNG',galleryAction='Enlarge image',langLabel='Language',readme='README.md')}
files=['WHOLE_BEFORE','WHOLE_AFTER','BAY0_BEFORE','BAY0_AFTER','BAY1_BEFORE','BAY1_AFTER','D4_FLOOR_MAP','D9_FLOOR_MAP']
for lang,c in COPY.items():
 page='index.html' if lang=='ja' else 'en.html'
 docroot='docs/ja/guide/' if lang=='ja' else 'docs/guide/'
 docfiles=['getting-started.md','model-guide.md','verification.md','versions.md']
 # README anchors remain stable even if the English guide filename convention changes.
 docurls=[f'{REPO}/blob/main/{docroot}{p}' for p in docfiles]

 glyph='<svg aria-hidden="true" viewBox="0 0 64 64"><path fill="currentColor" d="M5 39h54L46 54H18zM24 34h17l-4-20H29zM31 5h3v12"/></svg>'
 headings=['compare','gallery','models','verify']
 nav=''.join(f'<a class="desktop" href="#{a}">{n}</a>' for a,n in zip(headings,c['nav']))
 gallery=''.join(f'<button type="button" class="{"map" if i>5 else ""}" data-image="assets/{f.lower()}.webp" data-alt="{escape(c["galleryNames"][i])}" data-original="{RAW}/images/{f}.png" aria-label="{c["galleryAction"]}: {escape(c["galleryNames"][i])}"><img src="assets/{f.lower()}.webp" width="{1800}" height="{695 if i>5 else 1012}" alt="{escape(c["galleryNames"][i])}" loading="lazy"><span>{c["galleryNames"][i]} <b aria-hidden="true">↗</b></span></button>' for i,f in enumerate(files))
 controls=''.join(f'<button type="button" data-view="{v}" data-description="{escape(c["viewDescriptions"][i])}" aria-pressed="{str(i==1).lower()}">{c["views"][i]}</button>' for i,v in enumerate(['whole','bay0','bay1']))
 links=''.join(f'<a href="{u}">{t} ↗</a>' for u,t in zip(docurls,c['docs']))
 html=f'''<!doctype html>
<html lang="{lang}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{c['title']}</title><meta name="description" content="{c['desc']}"><meta name="theme-color" content="#15272e"><meta property="og:type" content="website"><meta property="og:title" content="{c['title']}"><meta property="og:description" content="{c['desc']}"><meta property="og:image" content="https://sunwood-ai-labs.github.io/witness-battleship/assets/whole_after.webp"><meta property="og:url" content="https://sunwood-ai-labs.github.io/witness-battleship/{'' if lang=='ja' else 'en.html'}"><link rel="canonical" href="https://sunwood-ai-labs.github.io/witness-battleship/{'' if lang=='ja' else 'en.html'}"><link rel="alternate" hreflang="ja" href="https://sunwood-ai-labs.github.io/witness-battleship/"><link rel="alternate" hreflang="en" href="https://sunwood-ai-labs.github.io/witness-battleship/en.html"><link rel="icon" href="assets/favicon.svg" type="image/svg+xml"><link rel="stylesheet" href="styles.css"><script src="app.js" defer></script></head>
<body><a class="skip" href="#main">{c['skip']}</a><header class="topbar"><div class="wrap"><a class="brand" href="{page}" aria-label="WITNESS home">{glyph}WITNESS</a><nav aria-label="{'メイン' if lang=='ja' else 'Main'}">{nav}<span class="lang" aria-label="{c['langLabel']}"><a href="index.html" {'aria-current="page"' if lang=='ja' else ''} lang="ja">JA</a> / <a href="en.html" {'aria-current="page"' if lang=='en' else ''} lang="en">EN</a></span></nav></div></header>
<main id="main"><div class="wrap hero"><div class="hero-meta eyebrow"><span>{c['edition']}</span><span class="status">{c['status']}</span></div><h1>WITNESS</h1><div class="hero-sub"><h2>{c['subtitle']}</h2><p>{c['intro']}</p></div><div class="hero-image"><img src="assets/whole_after.webp" width="1800" height="1012" alt="{'白い船体と暗色の艦橋を持つ架空の戦艦 WITNESS の全景比較' if lang=='ja' else 'Whole-view comparison of WITNESS with a white hull and dark angular bridge'}" fetchpriority="high"><span class="image-label">FIG. 01 — WHOLE VIEW / AFTER</span></div><div class="hero-rule"><span>{c['heroNote']}</span><span class="mono">FreeCAD · FCStd · BRep</span></div><div class="hero-actions"><a class="button primary" href="#models">{c['cta']} <span aria-hidden="true">↓</span></a><a class="button" href="{REPO}">{c['repo']} <span aria-hidden="true">↗</span></a></div></div>
<div class="wrap"><section id="compare"><div class="section-heading"><span class="section-no">01 / COMPARISON</span><div><h2>{c['compareTitle']}</h2><p>{c['compareIntro']}</p></div></div><div class="compare-controls">{controls}<span class="compare-hint">{c['hint']}</span></div><div class="comparison" role="group" aria-label="Before / After"><img class="before" src="assets/bay0_before.webp" width="1800" height="1012" alt="BAY 0 — Before" loading="lazy"><img class="after" src="assets/bay0_after.webp" width="1800" height="1012" alt="BAY 0 — After" loading="lazy"><span class="compare-badge">BEFORE</span><span class="compare-badge right">AFTER</span></div><div class="slider-row"><label for="split">{c['slider']}</label><input type="range" id="split" min="0" max="100" value="50" aria-describedby="compare-description"><output id="split-value" for="split">50%</output></div><p class="compare-note" id="compare-description" aria-live="polite">{c['viewDescriptions'][1]}</p><p class="compare-note">{c['compareNote']}</p></section>
<section id="gallery"><div class="section-heading"><span class="section-no">02 / VISUAL ARCHIVE</span><div><h2>{c['galleryTitle']}</h2><p>{c['galleryIntro']}</p></div></div><div class="gallery">{gallery}</div></section>
<section id="models"><div class="section-heading"><span class="section-no">03 / MODEL REGISTER</span><div><h2>{c['modelsTitle']}</h2><p>{c['modelsIntro']}</p></div></div><div class="model-grid"><article class="model"><span class="version">V62</span><span class="tag">BASELINE</span><h3>{c['v62Title']}</h3><p>{c['v62Desc']}</p><div class="model-detail">{c['v62Detail']}</div><a class="button" href="{docurls[0]}">{c['restore']} <span aria-hidden="true">↗</span></a></article><article class="model"><span class="version">V102</span><span class="tag">LOCAL COMPARISON</span><h3>{c['v102Title']}</h3><p>{c['v102Desc']}</p><div class="model-detail">{c['v102Detail']}</div><a class="button primary" href="{RAW}/cad/WITNESS_V102_PUBLIC.FCStd">{c['download']} <span aria-hidden="true">↓</span></a></article></div><div class="progress"><div><h3>{c['progressTitle']}</h3><div class="bays" aria-hidden="true">{''.join('<i class="done"></i>' if n<2 else '<i></i>' for n in range(14))}</div><p>{c['progressDesc']}</p></div><div class="numbers"><div class="stat"><strong>2<span style="font-size:24px">/14</span></strong><small>{c['verified']}</small></div><div class="stat"><strong>0</strong><small>{c['adopted']}</small></div></div></div></section>
<section id="verify"><div class="section-heading"><span class="section-no">04 / VERIFICATION</span><div><h2>{c['verifyTitle']}</h2><p>{c['verifyIntro']}</p></div></div><div class="verify-grid"><div><ul class="check-list">{''.join('<li>'+x+'</li>' for x in c['checks'])}</ul><div class="doc-links">{links}</div></div><div><pre class="terminal"><code><span class="prompt">$</span> git clone {REPO}.git
<span class="prompt">$</span> cd witness-battleship
<span class="prompt">$</span> python scripts/verify_files.py
<span class="prompt">$</span> python scripts/restore_v62.py</code></pre><p class="small">{c['verifyNote']}</p></div></div></section><div class="closing" id="download"><div><h2>{c['closingTitle']}</h2><p>{c['closingDesc']}</p></div><a class="button primary" href="{docurls[0]}">{c['start']} <span aria-hidden="true">↗</span></a></div></div></main>
<footer><div class="wrap"><p>WITNESS / {c['footer']}</p><p>{c['rights']} <a href="{REPO}/blob/main/{c['readme']}">README ↗</a></p></div></footer><dialog class="modal" id="viewer" aria-labelledby="viewer-title"><div class="modal-head"><strong id="viewer-title"></strong><button type="button">{c['close']} ×</button></div><img src="assets/whole_after.webp" alt=""><p><a id="original" href="{RAW}/images/WHOLE_AFTER.png">{c['original']} ↗</a></p></dialog></body></html>'''
 (ROOT/page).write_text(html,encoding='utf-8')
print('Built index.html and en.html')
